-- Recipe tags (base, protein, lifestyle, country), set when a recipe is created or edited. Existing recipes get
-- them filled in once from their ingredients, with the same word lists the app suggests tags with.
-- Generated by deploy/make-tags-sql.ts.
alter table public.recipes
  add column if not exists base_tags text[] not null default '{}',
  add column if not exists protein_tags text[] not null default '{}',
  add column if not exists lifestyle text check (lifestyle in ('Vegan', 'Vegetarian', 'Omnivore')),
  add column if not exists country text;
alter table public.cookbook_recipes
  add column if not exists base_tags text[] not null default '{}',
  add column if not exists protein_tags text[] not null default '{}',
  add column if not exists lifestyle text check (lifestyle in ('Vegan', 'Vegetarian', 'Omnivore'));

create or replace function pg_temp.recipe_tags(raw text)
returns table (base_tags text[], protein_tags text[], lifestyle text)
language sql immutable as $fn$
  select array_remove(array[case when t ~ ('(^|[^a-zäöüß])' || 'rice') or t ~ ('(^|[^a-zäöüß])' || 'risotto') then 'Rice' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'pasta') or t ~ ('(^|[^a-zäöüß])' || 'spaghetti') or t ~ ('(^|[^a-zäöüß])' || 'penne') or t ~ ('(^|[^a-zäöüß])' || 'fusilli') or t ~ ('(^|[^a-zäöüß])' || 'linguine') or t ~ ('(^|[^a-zäöüß])' || 'tagliatelle') or t ~ ('(^|[^a-zäöüß])' || 'macaroni') or t ~ ('(^|[^a-zäöüß])' || 'lasagn') or t ~ ('(^|[^a-zäöüß])' || 'gnocchi') or t ~ ('(^|[^a-zäöüß])' || 'noodle') or t ~ ('(^|[^a-zäöüß])' || 'ramen') or t ~ ('(^|[^a-zäöüß])' || 'udon') or t ~ ('(^|[^a-zäöüß])' || 'soba') then 'Pasta & noodles' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'potato') or t ~ ('(^|[^a-zäöüß])' || 'rösti') or t ~ ('(^|[^a-zäöüß])' || 'rosti') or t ~ ('(^|[^a-zäöüß])' || 'fries') or t ~ ('(^|[^a-zäöüß])' || 'hash brown') then 'Potatoes' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'bread') or t ~ ('(^|[^a-zäöüß])' || 'toast') or t ~ ('(^|[^a-zäöüß])' || 'tortilla') or t ~ ('(^|[^a-zäöüß])' || 'wrap') or t ~ ('(^|[^a-zäöüß])' || 'pita') or t ~ ('(^|[^a-zäöüß])' || 'bun') or t ~ ('(^|[^a-zäöüß])' || 'bagel') or t ~ ('(^|[^a-zäöüß])' || 'naan') or t ~ ('(^|[^a-zäöüß])' || 'baguette') or t ~ ('(^|[^a-zäöüß])' || 'sourdough') then 'Bread & wraps' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'oat') or t ~ ('(^|[^a-zäöüß])' || 'granola') or t ~ ('(^|[^a-zäöüß])' || 'muesli') or t ~ ('(^|[^a-zäöüß])' || 'quinoa') or t ~ ('(^|[^a-zäöüß])' || 'couscous') or t ~ ('(^|[^a-zäöüß])' || 'bulgur') or t ~ ('(^|[^a-zäöüß])' || 'barley') or t ~ ('(^|[^a-zäöüß])' || 'polenta') or t ~ ('(^|[^a-zäöüß])' || 'millet') then 'Oats & grains' end]::text[], null),
    array_remove(array[case when t ~ ('(^|[^a-zäöüß])' || 'chicken') then 'Chicken' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'beef') or t ~ ('(^|[^a-zäöüß])' || 'steak') or t ~ ('(^|[^a-zäöüß])' || 'veal') then 'Beef' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'pork') or t ~ ('(^|[^a-zäöüß])' || 'bacon') or t ~ ('(^|[^a-zäöüß])' || 'ham') or t ~ ('(^|[^a-zäöüß])' || 'prosciutto') or t ~ ('(^|[^a-zäöüß])' || 'sausage') or t ~ ('(^|[^a-zäöüß])' || 'chorizo') then 'Pork' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'lamb') then 'Lamb' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'turkey') then 'Turkey' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'fish') or t ~ ('(^|[^a-zäöüß])' || 'salmon') or t ~ ('(^|[^a-zäöüß])' || 'tuna') or t ~ ('(^|[^a-zäöüß])' || 'cod') or t ~ ('(^|[^a-zäöüß])' || 'trout') or t ~ ('(^|[^a-zäöüß])' || 'mackerel') or t ~ ('(^|[^a-zäöüß])' || 'sardine') or t ~ ('(^|[^a-zäöüß])' || 'anchov') or t ~ ('(^|[^a-zäöüß])' || 'shrimp') or t ~ ('(^|[^a-zäöüß])' || 'prawn') or t ~ ('(^|[^a-zäöüß])' || 'crab') or t ~ ('(^|[^a-zäöüß])' || 'squid') or t ~ ('(^|[^a-zäöüß])' || 'scallop') or t ~ ('(^|[^a-zäöüß])' || 'mussel') or t ~ ('(^|[^a-zäöüß])' || 'seafood') then 'Fish & seafood' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'egg') then 'Eggs' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'tofu') or t ~ ('(^|[^a-zäöüß])' || 'tempeh') or t ~ ('(^|[^a-zäöüß])' || 'seitan') or t ~ ('(^|[^a-zäöüß])' || 'edamame') then 'Tofu & tempeh' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'lentil') or t ~ ('(^|[^a-zäöüß])' || 'chickpea') or t ~ ('(^|[^a-zäöüß])' || 'bean') or t ~ ('(^|[^a-zäöüß])' || 'dal') or t ~ ('(^|[^a-zäöüß])' || 'hummus') or t ~ ('(^|[^a-zäöüß])' || 'falafel') then 'Legumes' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'skyr') or t ~ ('(^|[^a-zäöüß])' || 'quark') or t ~ ('(^|[^a-zäöüß])' || 'yogurt') or t ~ ('(^|[^a-zäöüß])' || 'yoghurt') or t ~ ('(^|[^a-zäöüß])' || 'cottage') or t ~ ('(^|[^a-zäöüß])' || 'cheese') or t ~ ('(^|[^a-zäöüß])' || 'ricotta') or t ~ ('(^|[^a-zäöüß])' || 'feta') or t ~ ('(^|[^a-zäöüß])' || 'mozzarella') or t ~ ('(^|[^a-zäöüß])' || 'parmesan') or t ~ ('(^|[^a-zäöüß])' || 'halloumi') or t ~ ('(^|[^a-zäöüß])' || 'paneer') then 'Dairy' end,
    case when t ~ ('(^|[^a-zäöüß])' || 'whey') or t ~ ('(^|[^a-zäöüß])' || 'protein powder') or t ~ ('(^|[^a-zäöüß])' || 'casein') or t ~ ('(^|[^a-zäöüß])' || 'protein shake') then 'Protein powder' end]::text[], null),
    case when t ~ ('(^|[^a-zäöüß])' || 'chicken') or t ~ ('(^|[^a-zäöüß])' || 'beef') or t ~ ('(^|[^a-zäöüß])' || 'steak') or t ~ ('(^|[^a-zäöüß])' || 'veal') or t ~ ('(^|[^a-zäöüß])' || 'pork') or t ~ ('(^|[^a-zäöüß])' || 'bacon') or t ~ ('(^|[^a-zäöüß])' || 'ham') or t ~ ('(^|[^a-zäöüß])' || 'prosciutto') or t ~ ('(^|[^a-zäöüß])' || 'sausage') or t ~ ('(^|[^a-zäöüß])' || 'chorizo') or t ~ ('(^|[^a-zäöüß])' || 'lamb') or t ~ ('(^|[^a-zäöüß])' || 'turkey') or t ~ ('(^|[^a-zäöüß])' || 'duck') or t ~ ('(^|[^a-zäöüß])' || 'fish') or t ~ ('(^|[^a-zäöüß])' || 'salmon') or t ~ ('(^|[^a-zäöüß])' || 'tuna') or t ~ ('(^|[^a-zäöüß])' || 'cod') or t ~ ('(^|[^a-zäöüß])' || 'trout') or t ~ ('(^|[^a-zäöüß])' || 'mackerel') or t ~ ('(^|[^a-zäöüß])' || 'sardine') or t ~ ('(^|[^a-zäöüß])' || 'anchov') or t ~ ('(^|[^a-zäöüß])' || 'shrimp') or t ~ ('(^|[^a-zäöüß])' || 'prawn') or t ~ ('(^|[^a-zäöüß])' || 'crab') or t ~ ('(^|[^a-zäöüß])' || 'squid') or t ~ ('(^|[^a-zäöüß])' || 'scallop') or t ~ ('(^|[^a-zäöüß])' || 'mussel') or t ~ ('(^|[^a-zäöüß])' || 'seafood') or t ~ ('(^|[^a-zäöüß])' || 'gelatin') or t ~ ('(^|[^a-zäöüß])' || 'fish sauce') then 'Omnivore' when t ~ ('(^|[^a-zäöüß])' || 'egg') or t ~ ('(^|[^a-zäöüß])' || 'milk') or t ~ ('(^|[^a-zäöüß])' || 'butter') or t ~ ('(^|[^a-zäöüß])' || 'cream') or t ~ ('(^|[^a-zäöüß])' || 'cheese') or t ~ ('(^|[^a-zäöüß])' || 'yogurt') or t ~ ('(^|[^a-zäöüß])' || 'yoghurt') or t ~ ('(^|[^a-zäöüß])' || 'skyr') or t ~ ('(^|[^a-zäöüß])' || 'quark') or t ~ ('(^|[^a-zäöüß])' || 'cottage') or t ~ ('(^|[^a-zäöüß])' || 'ricotta') or t ~ ('(^|[^a-zäöüß])' || 'feta') or t ~ ('(^|[^a-zäöüß])' || 'mozzarella') or t ~ ('(^|[^a-zäöüß])' || 'parmesan') or t ~ ('(^|[^a-zäöüß])' || 'halloumi') or t ~ ('(^|[^a-zäöüß])' || 'paneer') or t ~ ('(^|[^a-zäöüß])' || 'ghee') or t ~ ('(^|[^a-zäöüß])' || 'honey') or t ~ ('(^|[^a-zäöüß])' || 'whey') or t ~ ('(^|[^a-zäöüß])' || 'casein') or t ~ ('(^|[^a-zäöüß])' || 'mayo') then 'Vegetarian' else 'Vegan' end
  from (select replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(' ' || raw || ' '), 'eggplant', ' '), 'green bean', ' '), 'coconut milk', ' '), 'almond milk', ' '), 'oat milk', ' '), 'soy milk', ' '), 'rice milk', ' '), 'peanut butter', ' '), 'almond butter', ' '), 'cocoa butter', ' '), 'vegan', ' '), 'plant-based', ' '), 'plant based', ' '), 'cream of tartar', ' '), 'rice vinegar', ' '), 'jelly bean', ' ') as t) x
$fn$;

update public.recipes r set base_tags = f.base_tags, protein_tags = f.protein_tags, lifestyle = f.lifestyle,
  country = coalesce(r.country, (
    select case lower(tag) when 'italian' then 'Italy' when 'mexican' then 'Mexico' when 'indian' then 'India' when 'japanese' then 'Japan' when 'thai' then 'Thailand' when 'greek' then 'Greece' when 'chinese' then 'China' when 'french' then 'France' when 'american' then 'USA' when 'korean' then 'Korea' when 'spanish' then 'Spain' when 'turkish' then 'Turkey' when 'vietnamese' then 'Vietnam' when 'middle-eastern' then 'Middle East' when 'swiss' then 'Switzerland' end
    from unnest(r.cuisine_tags) tag
    where lower(tag) in ('italian', 'mexican', 'indian', 'japanese', 'thai', 'greek', 'chinese', 'french', 'american', 'korean', 'spanish', 'turkish', 'vietnamese', 'middle-eastern', 'swiss') limit 1))
from (
  select r2.id, (pg_temp.recipe_tags(r2.name || ' | ' || coalesce((
    select string_agg(i.name, ' | ') from public.recipe_ingredients ri join public.ingredients i on i.id = ri.ingredient_id
    where ri.recipe_id = r2.id), ''))).*
  from public.recipes r2
) f
where f.id = r.id and r.lifestyle is null;

update public.cookbook_recipes c set base_tags = f.base_tags, protein_tags = f.protein_tags, lifestyle = f.lifestyle
from (
  select c2.id, (pg_temp.recipe_tags(c2.name || ' | ' || array_to_string(c2.ingredients, ' | '))).*
  from public.cookbook_recipes c2
) f
where f.id = c.id and c.lifestyle is null;
